 perms=([] if state['profile']=='denied' else ['dashboard.access','content.read','dashboard.import.foundation_sample.read','dashboard.import.foundation_sample.create','dashboard.import.foundation_sample.commit','dashboard.export.foundation_sample.read','dashboard.export.foundation_sample.create','dashboard.export.foundation_sample.download']); actions=[{'action':'read','permissionKey':p,'decision':'allow','reason':'granted_by_persisted_permission','scope':{'kind':'global'}} for p in perms]
