class H(BaseHTTPRequestHandler):
 def log_message(self,*a): pass
 def cors(self):
  self.send_header('Access-Control-Allow-Origin','http://127.0.0.1:4420'); self.send_header('Access-Control-Allow-Credentials','true'); self.send_header('Access-Control-Allow-Headers','Content-Type,Content-Length,If-Match,Idempotency-Key,X-Data-Job-Upload-Token,Accept'); self.send_header('Access-Control-Allow-Methods','GET,POST,PUT,OPTIONS'); self.send_header('Access-Control-Expose-Headers','Content-Disposition,X-Content-Type-Options,Cache-Control,Referrer-Policy')
