   identity=(self.headers.get('Idempotency-Key'),raw.hex())
   if state['finalize_identity'] is None: state['finalize_identity']=identity; state['jobs']=1; state['artifacts']=1; state['import_status']='preview_ready'; result=imp('uploaded'); result['version']=2; return self.sendj({'data':result,'meta':{'replayed':False}})
